function translate(){document.documentElement.lang=language;document.title='Security Canvas — weownit.net';document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));document.querySelectorAll('[data-canvas-label]').forEach(el=>el.setAttribute(el.tagName==='IFRAME'?'title':'aria-label',t(el.dataset.canvasLabel)));document.querySelectorAll('[data-lang]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.lang===language)));$('begin').textContent=t('begin');renderChoices();if(state.path.length)renderWorkspace();try{const child=$('current-frame').contentDocument;child?.querySelector('[data-lang="'+language+'"]')?.click();}catch(_){}window.SiteI18n.syncInternalLanguageLinks(language);setComparisonButtons();}

function renderChoices(){
 $('concerns').innerHTML=C.CONCERNS.map(k=>`<button class="concern" data-concern="${k}" aria-pressed="${state.concern===k}"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.25" aria-hidden="true">${icons[k]}</svg><strong>${t(k)}</strong><small>${t(k+'Hint')}</small>${state.concern===k?'<span class="check" aria-hidden="true">✓</span>':''}</button>`).join('');
 $('vendors').innerHTML=Object.entries(C.VENDORS).map(([k,v])=>`<button data-vendor="${k}" aria-pressed="${state.vendor===k}">${v}</button>`).join('');
 $('begin').disabled=!state.concern&&!state.vendor;
 $('selection-hint').textContent=state.concern?C.VENDORS[state.vendor||'fortinet']+' · '+t(state.concern):t('chooseFirst');
}
function begin(){state.vendor??='fortinet';state.concern??='hardening';state.path=C.route(state.concern,state.vendor);state.index=0;state.results={};state.buffers={};state.notes={};state.samples={};state.asset=Case.asset();state.bridge=null;state.revision++;$('start').hidden=true;$('workspace').hidden=false;renderWorkspace();focusPanel();}
function restart(){C.cancel?.();state.revision++;state.running=false;state.path=[];state.results={};state.buffers={};state.samples={};state.notes={};state.index=0;state.asset=Case.asset();state.bridge=null;state.view='canvas';$('start').hidden=false;$('workspace').hidden=true;$('comparison').hidden=true;setComparisonButtons();renderChoices();$('save-case').hidden=true;$('case-status').hidden=true;$('begin').focus();}
function setComparisonButtons(){$('save-case').hidden=!state.path.length||state.view==='current';$('canvas-view').hidden=state.view!=='current';$('current-view').hidden=state.view==='current';$('bridge-actions').hidden=!state.bridge||state.view!=='current';$('canvas-view').setAttribute('aria-pressed',String(state.view==='canvas'));}
function compare(anchor=''){state.view='current';$('start').hidden=true;$('workspace').hidden=true;$('comparison').hidden=false;const frame=$('current-frame'),next='./tools-existing.html?lang='+language+(anchor?'#'+anchor:'');if(!frame.src.includes('tools-existing.html')||anchor){const oldURL=new URL(frame.src,location.href),newURL=new URL(next,location.href);if(oldURL.pathname+oldURL.search!==newURL.pathname+newURL.search)frame.classList.remove('is-ready');frame.src=next;}setComparisonButtons();prepareFullTool();$('comparison').querySelector('h1').focus?.();}
function canvasView(){state.view='canvas';$('comparison').hidden=true;$('start').hidden=!!state.path.length;$('workspace').hidden=!state.path.length;setComparisonButtons();}
function focusPanel(){const heading=$('tool-heading');if(heading){heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true});$('workspace').scrollIntoView({behavior:'auto',block:'start'});}}
function renderWorkspace(){
 $('save-case').hidden=false;
 $('case-context').textContent=C.VENDORS[state.vendor]+' / '+t(state.concern);
 $('path-title').textContent=t(state.concern)+'.';
 const note=state.concern==='change'&&['cisco','checkpoint'].includes(state.vendor);$('coverage-note').hidden=!note;$('coverage-note').textContent=note?t(state.vendor==='cisco'?'ciscoNote':'cpNote'):'';
 $('progress').innerHTML=[...state.path,'summary'].map((k,i)=>{const result=state.results[k],skipped=!!result?.skipped,reviewed=!!result&&!skipped,status=skipped?'skipped':reviewed?'reviewed':'';return `<li class="${i===state.index?'active':status}" ${i===state.index?'aria-current="step"':''}><span class="number" aria-hidden="true">${skipped?'—':reviewed?'✓':'0'+(i+1)}</span>${esc(kindLabel(k))}${status?`<span class="progress-status"> · ${t(status)}</span>`:''}</li>`;}).join('');
 if(state.index===state.path.length)renderSummary();else renderTool();renderPreview();
}
function field(id,label,value,extra=''){return `<div class="input-block"><label for="${id}">${esc(label)}</label><input id="${id}" value="${esc(value)}" ${extra}></div>`;}
function textarea(id,label,value,extra=''){return `<div class="input-block"><label for="${id}">${esc(label)}</label><textarea id="${id}" spellcheck="false" autocomplete="off" autocapitalize="off" maxlength="1048576" ${extra}>${esc(value)}</textarea></div>`;}
function fileField(target){return `<div class="input-block"><label for="upload-${target}">${t('upload')}</label><input type="file" id="upload-${target}" data-upload="${target}" accept=".txt,.log,.syslog,.conf,.cfg,.json,.ndjson,.xml,.csv"><p class="file-note">${t('fileLimit')}</p></div>`;}
function limitText(k){return t(k==='policy'||k==='change'?'policyLimits':k+'Limits');}
function formats(k){if(k==='triage')return 'FortiOS key=value · PAN-OS CSV · Cisco IOS / IOS XE / ASA syslog · Check Point JSON';if(k==='hardening')return {fortinet:'FortiGate CLI / REST JSON',paloalto:'PAN-OS CLI set / XML',cisco:'Cisco IOS / IOS XE CLI',checkpoint:'Gaia Clish / Management API JSON'}[state.vendor];return {fortinet:'FortiOS policy CLI / REST JSON',paloalto:'PAN-OS CLI set / XML / JSON',checkpoint:'Check Point Management API JSON'}[state.vendor]+' · weownit review snapshot JSON / XML';}
function renderTool(){
 const k=key(),b=buffer(k);let form='';
 if(['hardening','policy','triage','change'].includes(k)){
  if(k==='hardening')form+=field('reference',t('deviceRef'),b.reference,'maxlength="120" required');
  if(k==='triage')form+=`<div class="field-row"><div class="input-block"><label for="source-mode">${t('sourceMode')}</label><select id="source-mode">${['auto','fortinet','paloalto','cisco','cisco-ios','cisco-asa','checkpoint','windows','linux'].map(v=>`<option value="${v}" ${v===b.mode?'selected':''}>${v==='auto'?t('auto'):v}</option>`).join('')}</select></div>${field('timezone',t('timezone'),b.timezone,'maxlength="6" pattern="[+-][0-9]{2}:[0-9]{2}"')}</div>`;
  if(k==='triage')form+=`<details class="tool-details"><summary>${t('scope')}</summary><div class="field-row">${field('evidence-year',t('year'),b.year||'','maxlength="4"')}${field('evidence-host',t('host'),b.host||'','maxlength="512"')}</div></details>`;
  form+=textarea('current-input',t(k==='triage'?'evidenceInput':'currentConfig'),b.current)+fileField('current');
  if(k==='hardening')form+=`<details class="tool-details" ${b.before?'open':''}><summary>${t('earlier')}</summary>${textarea('before-input',t('before'),b.before)}${fileField('before')}</details>`;
  if(k==='change')form+=textarea('after-input',t('proposedConfig'),b.after)+fileField('after')+scenarioBuilder(b);
  form+=`<button class="primary" type="submit">${t(k==='change'?'runChange':'run')}</button>`;
 }else if(k==='web')form+=field('domain-input',t('domain'),b.domain,'maxlength="2048" inputmode="url" required autocapitalize="none" autocomplete="url" placeholder="example.com"')+`<button class="primary" type="submit">${t('prepareWeb')}</button><p class="fine-print">${t('webPrivacy')}</p><div id="web-observation" hidden></div>`;
 else form+=assetForm()+field('cve-input','CVE',b.cve,'maxlength="28" required autocapitalize="characters" placeholder="CVE-2024-21762"')+`<button class="primary" type="submit">${t('runCve')}</button><p class="fine-print">${t('cvePrivacy')}</p>`;
 $('tool-panel').innerHTML=`<div class="tool-kicker">${state.index+1} / ${state.path.length} · ${C.VENDORS[state.vendor]}</div><div class="tool-title-row"><div><h2 id="tool-heading">${esc(toolName(k))}</h2><p class="engine-name">${esc(k==='hardening'?names[k].split(' · ')[0]:'')}</p></div><button class="demo-button" id="sample">${t(k==='web'?'recorded':'useSample')}</button></div><p class="tool-intro">${t(k+'Intro')}</p>${state.samples[k]?`<p class="sample-note">${t('sample')}</p>`:''}<form id="tool-form" class="tool-form" novalidate>${form}</form><p id="tool-status" class="status" role="status" aria-live="polite"></p><div id="tool-result" class="result" ${state.results[k]&&!state.results[k].skipped?'':'hidden'}></div><div class="input-block note-field"><label for="observation-note">${t('note')}</label><input id="observation-note" maxlength="300" value="${esc(state.notes[k]||'')}" autocomplete="off"></div><details class="tool-details"><summary>${t('limits')}</summary><p>${limitText(k)}</p>${['web','cve'].includes(k)?'':`<p>${t('formats')}: ${esc(formats(k))}</p>`}<p><button class="text-button" id="full-tool">${t('fullTool')}</button></p></details>`;
 $('tool-form').addEventListener('submit',e=>{e.preventDefault();return run();});$('sample').addEventListener('click',sample);
 $('observation-note').addEventListener('input',e=>state.notes[k]=e.target.value);
 $('full-tool').addEventListener('click',()=>{capture();state.bridge={kind:k,index:state.index,revision:state.revision};compare(anchors[k]);});
 $('tool-form').addEventListener('input',e=>{if(e.target.closest('#scenario-builder')||e.target.id==='scenarios-input')return;if(e.target.id.startsWith('asset-')){captureAsset();if(state.results.cve){state.results.cve.applicability=Case.applicability(state.asset,state.vendor,state.results.cve.result);renderResult(state.results.cve);}renderPreview();return;}if(e.target.id==='cve-input'){state.asset.assessment='unverified';state.asset.ack=false;state.asset.note='';$('asset-assessment').value='unverified';$('asset-ack').checked=false;$('asset-note').value='';}capture();invalidate(k);});
 if(k==='change')wireScenarios();
 if(k==='cve')document.querySelectorAll('[data-asset]').forEach(el=>el.addEventListener('change',()=>{captureAsset();if(state.results.cve){state.results.cve.applicability=Case.applicability(state.asset,state.vendor,state.results.cve.result);renderResult(state.results.cve);}renderPreview();}));
 $('tool-form').querySelectorAll('[data-upload]').forEach(el=>el.addEventListener('change',()=>upload(el)));
 if(state.results[k]&&!state.results[k].skipped)renderResult(state.results[k]);
 renderStepActions();
}
function capture(){const k=key();if(!k)return;const b=buffer(k);const fields={'current-input':'current','before-input':'before','after-input':'after',reference:'reference','source-mode':'mode',timezone:'timezone','evidence-year':'year','evidence-host':'host','domain-input':'domain','cve-input':'cve'};for(const [id,f]of Object.entries(fields))if($(id))b[f]=$(id).value;if(k==='cve')captureAsset();}
function invalidate(k){
 C.cancel?.();
 state.revision++;state.running=false;delete state.results[k];state.samples[k]=false;
 if(k==='policy'){delete state.results.change;buffer('change').current=buffer(k).current;buffer('change').after='';buffer('change').scenarios='[]';state.samples.change=false;}
 if(k==='change'&&buffer(k).current!==buffer('policy').current){delete state.results.policy;buffer('policy').current=buffer(k).current;state.samples.policy=false;}
 if(k==='web'&&$('web-observation')){$('web-observation').hidden=true;buffer(k).snapshot=null;}
 if($('tool-result'))$('tool-result').hidden=true;if($('tool-status'))$('tool-status').textContent='';renderStepActions();renderPreview();
}
async function upload(el){const f=el.files[0],k=key();if(!f)return;const revision=state.revision;try{if(f.size>1048576)throw new Error('tooLarge');const content=await f.text();if(revision!==state.revision||k!==key())return;if(content.includes('\0'))throw new Error('binary');const id={current:'current-input',before:'before-input',after:'after-input'}[el.dataset.upload];$(id).value=content;if(el.dataset.upload==='current')buffer(k).sourceName=f.name;capture();invalidate(k);}catch(e){setStatus(t(e.message==='tooLarge'?'tooLarge':e.code==='invalidScenarios'?'scenarioError':'error'),true);}finally{el.value='';}}
function setStatus(value,error=false){if($('tool-status')){$('tool-status').textContent=value;$('tool-status').className='status '+(error?'error':'success');}}
function renderStepActions(){const end=state.index===state.path.length;if(end){$('step-actions').innerHTML=`<button id="back-step" class="text-button">${t('back')}</button>`;}else{$('step-actions').innerHTML=`${state.index?`<button id="back-step" class="text-button">${t('back')}</button>`:''}<button id="skip-step" class="text-button">${t('skipStep')}</button><button id="next-step" class="primary" ${!state.results[key()]||state.running?'disabled':''}>${t(state.index===state.path.length-1?'finish':'continue')}</button>`;$('skip-step').addEventListener('click',()=>{state.revision++;state.running=false;state.results[key()]={kind:key(),skipped:true};next();});$('next-step').addEventListener('click',next);}if($('back-step'))$('back-step').addEventListener('click',()=>{capture();state.revision++;state.running=false;state.index--;renderWorkspace();focusPanel();});}
function next(){capture();state.revision++;state.running=false;state.index++;renderWorkspace();focusPanel();}
async function sample(){
 const k=key(),b=buffer(k);state.revision++;const revision=state.revision;state.running=false;delete state.results[k];state.path.slice(state.index+1).forEach(v=>delete state.results[v]);state.samples[k]=true;
 try{
  if(k==='hardening'){const d=window.VendorHardeningDemos[state.vendor];b.current=d.before;b.before='';b.reference=d.reference;}
  else if(k==='policy'||k==='change'){const d=C.policyLab(state.vendor);b.current=d.before;b.after=d.after;b.scenarios=JSON.stringify(d.scenarios,null,2);Object.assign(buffer('change'),b);state.samples.change=true;}
  else if(k==='triage'){const d=window.IncidentPlatformDemos.find(x=>x.key===(state.vendor==='cisco'?'cisco-ios':state.vendor));b.current=d.text;b.mode=d.mode;b.timezone=d.timezone||'+00:00';}
  else if(k==='cve'){b.cve={fortinet:'CVE-2024-21762',paloalto:'CVE-2024-3400',checkpoint:'CVE-2024-24919',cisco:'CVE-2023-20198'}[state.vendor];state.results[k]={kind:k,sample:true,result:null,id:b.cve};renderWorkspace();return;}
  else{b.domain='weownit.net';const response=await fetch('./assets/webcheck-weownit-snapshot.json');if(!response.ok)throw new Error('snapshot');const snapshot=await response.json();if(revision!==state.revision||key()!==k)return;b.snapshot=snapshot;renderWorkspace();prepareWeb();return;}
  renderWorkspace();await run();
 }catch(e){setStatus(t('error')+' ('+esc(e.code||e.message)+')',true);}
}
function prepareWeb(){const b=buffer('web');let domain;try{domain=C.domain(b.domain);}catch(e){setStatus(t('domainError'),true);return false;}b.domain=domain;$('domain-input').value=domain;
 const html=`<a class="external-link" href="https://web-check.xyz/check/${encodeURIComponent(domain)}" target="_blank" rel="noopener noreferrer">${t('openWeb')}</a><p class="fine-print">${t('webLimits')}</p>${b.snapshot&&domain==='weownit.net'?`<p class="sample-note">${t('recordedNote')} ${esc(b.snapshot.generatedAt)}</p><div class="result-stats"><div><strong>${esc(b.snapshot.checks?.dns?.state||'unknown')}</strong><span>DNS · ${t('recordedLabel')}</span></div><div><strong>${esc(b.snapshot.checks?.tls?.state||'unknown')}</strong><span>TLS · ${t('recordedLabel')}</span></div></div>`:''}<fieldset class="tool-details"><legend>${t('webOutcome')}</legend><div class="radio-options">${['followup','clear','unavailable'].map(v=>`<label><input type="radio" name="outcome" value="${v}" ${state.results.web?.outcome===v?'checked':''}>${t(v)}</label>`).join('')}</div></fieldset><button id="save-web" type="button" class="secondary">${t('saveObservation')}</button>`;
 $('web-observation').hidden=false;$('web-observation').innerHTML=html;$('save-web').addEventListener('click',()=>{const selected=document.querySelector('input[name=outcome]:checked');if(!selected){setStatus(t('webOutcome'),true);return;}state.results.web={kind:'web',domain,outcome:selected.value,sample:!!state.samples.web,recordedAt:b.snapshot?.generatedAt||null};setStatus(t('ready'));renderPreview();renderStepActions();});return true;
}
async function run(){
 if(state.running)return;capture();const k=key(),b=buffer(k),revision=state.revision;state.running=true;renderStepActions();setStatus(t(k==='cve'?'lookups':'running'));
 try{
  if(k==='web'){prepareWeb();return;}
  let result;
  if(k==='cve'){
   const id=b.cve.trim().toUpperCase();if(state.asset.assessment==='confirmed'&&Case.applicability(state.asset,state.vendor,null).status!=='confirmed'){setStatus(t('assetError'),true);return;}if(!validCve(id)){setStatus(t('cveError'),true);return;}
   const publicResult=await analyzeCve(id);result={kind:k,id,result:publicResult,sample:false,applicability:Case.applicability(state.asset,state.vendor,publicResult)};
  }else{
   if(!b.current.trim())throw new Error('empty');if([b.current,b.before,b.after].some(v=>new TextEncoder().encode(v).length>1048576)||new TextEncoder().encode(b.scenarios).length>131072)throw new Error('tooLarge');
   if(k==='hardening'&&!b.reference.trim())throw new Error('identity');
   if(k==='change'&&!b.after.trim())throw new Error('empty');
   await new Promise(resolve=>requestAnimationFrame(resolve));result=await C.inspectAsync(k,state.vendor,b);
  }
  if(revision!==state.revision||k!==key())return;
  state.results[k]={...result,sample:!!state.samples[k]&&k!=='cve'};
  renderResult(state.results[k]);setStatus(t('ready'));renderPreview();
 }catch(e){if(revision===state.revision&&k===key()){delete state.results[k];if($('tool-result'))$('tool-result').hidden=true;setStatus(window.ChangeConfidenceText?.copy[language]?.errors[e.code]||t(e.message==='empty'?'emptyError':e.message==='tooLarge'?'tooLarge':e.code==='invalidScenarios'?'scenarioError':e.code==='noSupportedSettings'?'unsupportedSettings':'error'),true);renderPreview();}}
 finally{if(revision===state.revision&&k===key()){state.running=false;renderStepActions();}}
}
function stats(entries){return `<div class="result-stats">${entries.map(([n,label])=>`<div><strong>${esc(n)}</strong><span>${esc(label)}</span></div>`).join('')}</div>`;}
function finding(title,detail,stateLabel='needsReview'){return `<article class="finding ${stateLabel==='observed'?'observed':''}"><span class="state ${stateLabel==='observed'?'observed':''}">${t(stateLabel)}</span><strong>${esc(title)}</strong><p>${esc(detail)}</p></article>`;}
function evidenceDetails(data){return `<details class="tool-details"><summary>${t('raw')}</summary><pre>${esc(JSON.stringify(data,null,2))}</pre></details>`;}
function renderResult(item){
 const k=item.kind,el=$('tool-result');el.hidden=false;let html='';
 if(k==='hardening'){
  const m=item.model;html=stats([[m.summary.fail,t('failed')],[m.summary.pass,t('passed')],[m.summary.unknown,t('unknown')]]);
  if(item.comparison)html+=stats([[item.comparison.summary.fixed,t('fixed')],[item.comparison.summary.regression,t('regressions')],[item.comparison.summary.notVerified,t('unknown')]])+`<p class="fine-print">${t('baselineRetest')}</p>`;
  const controls=m.controls.filter(c=>c.status==='fail').slice(0,4);html+=controls.map(c=>finding(Case.hardeningLabel(c.check,language),c.entity+' · '+c.evidence.map(e=>e.value).join(' · '))).join('');if(!controls.length)html+=`<p class="empty">${t('noFindings')}</p>`;
  if(item.sample&&!item.comparison)html+=`<button id="retest-sample" class="secondary">${t('tryRetest')}</button>`;html+=evidenceDetails({controls:m.controls,warnings:m.warnings,comparison:item.comparison});
 }else if(k==='policy'){
  const r=item.result;html=stats([[r.counts.rules,t('rules')],[r.counts.high,t('high')],[r.counts.medium,t('medium')]]);html+=r.findings.slice(0,4).map(f=>finding(findingLabel(f.code),f.ruleName+' · #'+f.ruleId+' · '+f.scope)).join('');if(!r.findings.length)html+=`<p class="empty">${t('noFindings')}</p>`;
  if(item.sample)html+=`<p class="fine-print">${t('diagramNote')}</p><div class="map"><div class="map-node">DMZ<small>192.0.2.25</small></div><span class="map-arrow">→</span><div class="map-node risky">${C.VENDORS[state.vendor]}<small>${t('broad')}</small></div><span class="map-arrow">→</span><div class="map-node risky">${t('database')}<small>198.51.100.20</small></div></div>${state.path[state.index+1]==='change'?`<button id="simulate" class="secondary">${t('runChange')} →</button>`:''}`;html+=evidenceDetails({findings:r.findings,coverage:r.coverage,warnings:r.warnings});
 }else if(k==='change'){
  const r=item.result;html=stats([[r.summary.pass,t('passed')],[r.summary.regression,t('regressions')],[r.summary.inconclusive,t('inconclusive')]])+`<p class="empty">${t(r.summary.regression||r.summary.inconclusive?'simFail':'simPass')}</p>`;
  if(item.sample)html+=`<p class="fine-print">${t('diagramNote')}</p><div class="map"><div class="map-node">DMZ<small>192.0.2.25</small></div><span class="map-arrow">→</span><div class="map-node safe">${C.VENDORS[state.vendor]}<small>${t('httpsOnly')}</small></div><span class="map-arrow">⊣</span><div class="map-node safe">${t('database')}<small>${t('block')}</small></div></div>`;
  if(item.decisionRecord){const d=window.ChangeConfidence.decision(r);html+=`<p><strong>WIT Change Confidence · ${esc(confidenceText(d.status.replaceAll('-','')))}</strong></p><p class="fine-print">${esc(confidenceText('limit'))}</p><button id="confidence-canvas-json" type="button" class="secondary">${esc(confidenceText('json'))}</button>`;}
  html+=`<div class="table-scroll"><table class="flow-table"><thead><tr><th>${t('flow')}</th><th>${t('before')}</th><th>${t('after')}</th><th>${t('expected')}</th></tr></thead><tbody>${r.flows.map(f=>`<tr><td>${esc(f.scenario.name)}<br><span class="muted">${esc(f.scenario.protocol)}/${esc(f.scenario.port)}</span></td><td class="verdict ${f.before.verdict}">${t(f.before.verdict)}</td><td class="verdict ${f.after.verdict}">${t(f.after.verdict)}</td><td>${t(f.scenario.expected)}</td></tr>`).join('')}</tbody></table></div>`+evidenceDetails({flows:r.flows,scope:r.scope});
 }else if(k==='triage'){
  const r=item.result;html=stats([[r.summary.unique,t('events')],[r.summary.high,t('high')],[r.summary.findings,t('findings')]]);html+=r.findings.slice(0,4).map(f=>finding(findingLabel(f.ruleId),(f.start||'')+' · '+(f.host||f.sourceIP||'')+' · '+t(f.priority==='high'?'high':'medium'))).join('');if(!r.findings.length)html+=`<p class="empty">${t('noFindings')}</p>`;html+=evidenceDetails({findings:r.findings,coverage:r.coverage,import:item.parsed.counts,skipped:item.parsed.skipped});
 }else if(k==='cve'){
  const r=item.result;html=item.sample?`<p class="empty">${t('cveSample')}</p>`:!r.cve?`<p class="empty">${t('cveUnavailable')}</p>`:`<h3>${esc(r.id)} · ${esc(r.cve.title)}</h3><p class="empty">${t(r.kev?.listed?'kevListed':'cveSignal')}</p>`+stats([[r.cve.cvss?.score??'—','CVSS'],[r.epss?((r.epss.probability*100).toFixed(2)+'%'):'—','EPSS'],[r.kev?r.kev.listed?t('yes'):t('no'):'—','CISA KEV']]);
  html+=applicabilityHTML(item);
  const home={fortinet:'https://www.fortiguard.com/psirt',paloalto:'https://security.paloaltonetworks.com/',checkpoint:'https://support.checkpoint.com/',cisco:'https://sec.cloudapps.cisco.com/security/center/publicationListing.x'}[state.vendor];html+=`<a class="external-link" href="${home}" target="_blank" rel="noopener noreferrer">${t('advisory')}</a>`;if(r)html+=evidenceDetails({checkedAt:r.checkedAt,sources:r.sources,vendors:r.vendors,priority:r.priority});
 }else if(k==='web'){prepareWeb();return;}
 el.innerHTML=html;if($('confidence-canvas-json'))$('confidence-canvas-json').addEventListener('click',()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(item.decisionRecord,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='weownit-change-confidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),500);});
 if($('retest-sample'))$('retest-sample').addEventListener('click',async()=>{const b=buffer('hardening'),d=window.VendorHardeningDemos[state.vendor];b.before=d.before;b.current=d.after;state.revision++;renderWorkspace();await run();});
 if($('simulate'))$('simulate').addEventListener('click',async()=>{next();await run();});
}
function nextAction(){
 const actions=Case.actions(state),first=actions.find(a=>a.code!=='collect');
 if(first)return actionInstruction(first);
 const summary=C.summary(state.path,state.results);
 if(!summary.completed||actions.some(a=>a.code==='collect'))return t('missingEvidence');
 if(state.concern==='change'&&!state.path.includes('change'))return t(state.vendor==='checkpoint'?'nextStaticPolicy':state.results.hardening?.comparison?'retestNext':'nextHardening');
 if(state.results.hardening?.comparison?.summary.fixed&&!state.results.hardening.comparison.summary.regression)return t('retestNext');
 return t('next'+state.concern[0].toUpperCase()+state.concern.slice(1));
}
function renderPreview(){if(!state.path.length)return;const final=state.index===state.path.length;$('action-preview').hidden=final;document.querySelector('.workspace-grid').classList.toggle('summary-view',final);if(final)return;const s=C.summary(state.path,state.results);$('action-preview').innerHTML=`<p class="eyebrow">${t('nextAction')}</p><h2>${t('summary')}</h2><p class="next-action">${nextAction()}</p><ul class="evidence-list">${state.path.map(k=>`<li><span>${esc(names[k].split(' · ')[0])}${k==='hardening'?'<br>'+t('hardening'):k==='policy'?'<br>'+t('policyReview'):k==='change'?'<br>'+t('simulation'):''}</span><span class="state ${C.signals(state.results[k]).state==='observed'?'observed':''}">${t(C.signals(state.results[k]).state)}</span></li>`).join('')}</ul><p class="small">${s.completed} / ${s.total} ${t('completed').toLowerCase()}</p><p class="fine-print">${t('planDisclaimer')}</p>`;}
function renderSummary(){
 const s=C.summary(state.path,state.results),sample=Object.values(state.results).some(v=>v.sample);$('tool-panel').innerHTML=`<p class="tool-kicker">${t('evidenceStatus')} · ${t(s.state)}</p><h2 id="tool-heading" class="summary-title">${t('summaryTitle')}</h2>${sample?`<p class="sample-note">${t('sample')}</p>`:''}<p class="tool-intro">${nextAction()}</p>${stats([[s.completed+' / '+s.total,t('completed')],[s.attention,t('reviewSignals')],[s.unknown,t('unresolved')]])}${targetedActionsHTML()}${state.path.map(k=>summaryEvidence(k)).join('')}<div class="summary-actions"><button id="report-download" class="primary">${t('reportDownload')}</button><button id="download" class="secondary">${t('download')}</button><button id="copy" class="secondary">${t('copy')}</button></div><a class="external-link" href="contact.html?lang=${language}">${t('consultant')}</a><details class="tool-details handoff"><summary>${t('shareSummary')}</summary><p class="fine-print">${t('handoffHint')}</p>${textarea('handoff-summary',t('handoffLabel'),enquirySummary())}<p class="fine-print">${t('handoffLocal')}</p><button id="handoff-open" type="button" class="secondary">${t('handoffOpen')}</button><p id="handoff-status" class="status" role="status" aria-live="polite"></p></details><p class="fine-print">${t('privacy')} ${t('planDisclaimer')}</p>`;
 $('report-download').addEventListener('click',downloadReport);$('handoff-summary').setAttribute('maxlength','2000');$('handoff-open').addEventListener('click',()=>{if(window.ReviewHandoff?.prepare($('handoff-summary').value,language)){location.href=new URL('contact.html?lang='+language+'#message-section',location.href).href;}else{$('handoff-status').textContent=t('handoffError');$('handoff-status').className='status error';}});
 $('download').addEventListener('click',download);$('copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(summaryText());toast(t('copied'));}catch(_){toast(t('copyFail'));}});renderStepActions();
}
function summaryEvidence(k){const r=state.results[k];let detail=t('notAssessed');if(r&&!r.skipped){if(k==='hardening')detail=r.model.summary.fail+' '+t('failed')+' · '+r.model.summary.unknown+' '+t('unknown');else if(k==='policy')detail=r.result.findings.length+' '+t('findings');else if(k==='triage')detail=r.result.summary.findings+' '+t('findings')+' / '+r.result.summary.unique+' '+t('events');else if(k==='change')detail=r.result.summary.pass+' '+t('passed')+' · '+r.result.summary.regression+' '+t('regressions')+' · '+r.result.summary.inconclusive+' '+t('inconclusive');else if(k==='web')detail=r.domain+' · '+t(r.outcome);else detail=r.id+' · '+t(r.sample?'cveSample':r.result?.cve?'cveSignal':'cveUnavailable');}return finding(toolName(k),detail+(state.notes[k]?' · '+state.notes[k]:''),C.signals(r).state);}
function summaryText(){const s=C.summary(state.path,state.results);return `weownit.net — Security Canvas\n${new Date().toISOString()}\n${C.VENDORS[state.vendor]} · ${t(state.concern)}\n${Object.values(state.results).some(v=>v.sample)?t('sample')+'\n':''}\n${t('nextAction')}: ${nextAction()}\n${t('completed')}: ${s.completed}/${s.total}\n${t('evidenceStatus')}: ${t(s.state)}\n\n${targetedActionsText()}\n\n${state.path.map(k=>{const el=document.createElement('div');el.innerHTML=summaryEvidence(k);return el.textContent;}).join('\n\n')}\n\n1. ${t('plan1')}: ${t('plan1Hint')}\n2. ${t('plan2')}: ${nextAction()}\n3. ${t('plan3')}: ${t('plan3Hint')}\n\n${t('planDisclaimer')}`;}

function enquirySummary(){
 const summary=C.summary(state.path,state.results);
 const lines=['weownit.net · Security Canvas',C.VENDORS[state.vendor]+' · '+t(state.concern)];
 if(Object.values(state.results).some(r=>r.sample))lines.push(t('sample'));
 lines.push(t('completed')+': '+summary.completed+'/'+summary.total,t('evidenceStatus')+': '+t(summary.state));
 for(const kind of state.path){const r=state.results[kind];let detail=t('notAssessed');if(r&&!r.skipped){if(kind==='hardening')detail=r.model.summary.fail+' '+t('failed')+' / '+r.model.summary.unknown+' '+t('unknown');else if(kind==='triage')detail=r.result.summary.findings+' '+t('findings')+' / '+r.result.summary.unique+' '+t('events');else if(kind==='policy')detail=r.result.findings.length+' '+t('findings');else if(kind==='change')detail=r.result.summary.pass+' '+t('passed')+' / '+r.result.summary.regression+' '+t('regressions')+' / '+r.result.summary.inconclusive+' '+t('inconclusive');else detail=t(kind==='web'?'declared':r.applicability?.status==='confirmed'?'observed':'partial');}lines.push(toolName(kind)+': '+detail);}
 lines.push(t('planDisclaimer'));return lines.join('\n');
}
function reportHTML(){
 const summary=C.summary(state.path,state.results),sample=Object.values(state.results).some(r=>r.sample);
 return '<!doctype html><html lang="'+language+'"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'; base-uri \'none\'; form-action \'none\'"><title>weownit · '+esc(t('reportTitle'))+'</title><style>body{font:15px/1.6 system-ui,sans-serif;max-width:960px;margin:40px auto;padding:0 20px;color:#16313b}h1,h2,h3{line-height:1.2}h1{font-size:32px}.target-action,.finding{border:1px solid #ccd8dc;padding:16px;margin:16px 0;break-inside:avoid}.fine-print,.muted{color:#526771}.state{font-size:12px;font-weight:bold}.action-ref,p{overflow-wrap:anywhere}a{color:#164b69}details{margin:10px 0}strong{display:inline-block;margin-right:5px}@media print{body{margin:0}details>summary{display:none}details>p{display:block!important}}</style></head><body><p>weownit.net · Security Canvas</p><h1>'+esc(t('reportTitle'))+'</h1><p>'+esc(C.VENDORS[state.vendor])+' · '+esc(t(state.concern))+'</p><p>'+esc(t('generated'))+': '+new Date().toISOString()+'</p>'+(sample?'<p>'+esc(t('sample'))+'</p>':'')+'<h2>'+esc(t('evidenceStatus'))+' · '+esc(t(summary.state))+'</h2><p>'+esc(t('completed'))+': '+summary.completed+'/'+summary.total+'</p><h2>'+esc(t('nextAction'))+'</h2><p>'+esc(nextAction())+'</p>'+targetedActionsHTML().replaceAll('<details','<details open')+state.path.map(summaryEvidence).join('')+'<h2>'+esc(t('limits'))+'</h2><ul>'+state.path.map(k=>'<li>'+esc(toolName(k))+': '+esc(t(k==='policy'?'policyLimits':k==='change'?'policyLimits':k+'Limits'))+'</li>').join('')+'</ul><p>'+esc(t('planDisclaimer'))+'</p><p>'+esc(t('reportPrivacy'))+'</p></body></html>';
}
