function actionInstruction(a){if(a.kind==='hardening'&&Case.remedy(a.code,language))return Case.remedy(a.code,language);const map={anyAny:'restrict',broadAllow:'restrict',adminService:'restrict',noLogging:'logging',noProtection:'profile'};return t('action_'+(map[a.code]||(['collect','verifyMissing','traffic','retestTraffic','webReview','verifyAsset','patchAdvisory'].includes(a.code)?a.code:a.kind==='triage'?'triage':'policy')));}
function actionTitle(a){if(a.regression)return t('regressionAction')+' · '+Case.hardeningLabel(a.code,language);if(a.kind==='hardening'&&Case.remedy(a.code,language))return Case.hardeningLabel(a.code,language);if(a.code==='verifyMissing'||a.code==='collect')return t('unknownEvidence');if(a.code==='traffic'||a.code==='retestTraffic')return t('trafficBuilder');if(a.kind==='cve')return t(a.applicability.status);if(a.kind==='web')return t('exposure');return findingLabel(a.code);}
function actionRetest(a){return t('retest_'+({hardening:'config',policy:'policy',change:'policy',triage:'triage',cve:'cve',web:'web'}[a.kind]));}
function actionCard(a){let source='';try{const u=new URL(a.source);if(u.protocol==='https:'&&!u.username&&!u.password)source=`<a class="mini-link" href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">${t('actionSource')} ↗</a>`;}catch(_){}return `<article class="target-action"><span class="state">${t(a.priority==='high'?'high':a.priority==='low'?'low':'medium')}</span><h3>${esc(actionTitle(a))}</h3><p class="action-ref">${esc(a.reference)}</p>${a.evidence?`<details class="action-evidence"><summary>${t('supportingEvidence')}</summary><p>${esc(a.evidence)}</p></details>`:''}<p><strong>${t('proposedAction')}</strong> ${esc(actionInstruction(a))}</p><p class="fine-print"><strong>${t('requiredRetest')}</strong> ${esc(actionRetest(a))}</p>${source}</article>`;}
function targetedActionsHTML(){const items=Case.actions(state);return `<section class="targeted-actions"><h3>${t('targetedActions')}</h3>${items.slice(0,3).map(actionCard).join('')}${items.length>3?`<details class="tool-details"><summary>${t('moreActions')} · ${items.length-3}</summary>${items.slice(3).map(actionCard).join('')}</details>`:''}${items.total>items.length?`<p class="fine-print">${t('actionLimit')}</p>`:''}</section>`;}
function targetedActionsText(){const items=Case.actions(state);return t('targetedActions')+'\n'+items.map((a,i)=>`${i+1}. ${actionTitle(a)} · ${a.reference}\n${t('supportingEvidence')}: ${a.evidence}\n${t('proposedAction')}: ${actionInstruction(a)}\n${t('requiredRetest')}: ${actionRetest(a)}${a.source?'\n'+a.source:''}`).join('\n\n')+(items.total>items.length?'\n'+t('actionLimit'):'');}
function assetForm(){const a=state.asset;return `<fieldset class="asset-context" id="asset-context"><legend>${t('assetContext')}</legend><div class="field-row">${field('asset-product',t('product'),a.product,'maxlength="120" data-asset')}${field('asset-version',t('version'),a.version,'maxlength="80" data-asset')}</div><details class="tool-details" ${a.assessment!=='unverified'?'open':''}><summary>${t('assessment')}</summary><div class="input-block"><label for="asset-assessment">${t('assessment')}</label><select id="asset-assessment" data-asset>${['unverified','potential','confirmed'].map(k=>`<option value="${k}" ${a.assessment===k?'selected':''}>${t(k)}</option>`).join('')}</select></div>${field('asset-advisory',t('advisoryURL'),a.advisoryURL,'maxlength="2048" data-asset inputmode="url"')}${field('asset-note',t('assetNote'),a.note,'maxlength="500" data-asset')}<label class="asset-ack"><input id="asset-ack" type="checkbox" data-asset ${a.ack?'checked':''}><span>${t('assetAck')}</span></label></details><p class="fine-print">${t('assetHint')}</p></fieldset>`;}
function captureAsset(){if(!$('asset-product'))return;const next={product:$('asset-product').value,version:$('asset-version').value,assessment:$('asset-assessment').value,advisoryURL:$('asset-advisory').value,note:$('asset-note').value,ack:$('asset-ack').checked};if(state.asset.assessment==='confirmed'&&['product','version','advisoryURL'].some(k=>next[k]!==state.asset[k])){next.assessment='unverified';next.ack=false;next.note='';$('asset-assessment').value='unverified';$('asset-ack').checked=false;$('asset-note').value='';}state.asset=next;}
function applicabilityHTML(item){const ap=Case.applicability(state.asset,state.vendor,item.result);return `<div class="applicability-result"><span class="state">${t(ap.status)}</span><p>${esc(ap.product)}${ap.version?' · '+esc(ap.version):''}</p>${ap.note?`<p>${esc(ap.note)}</p>`:''}<p class="fine-print">${t('assetHint')}</p>${ap.url?`<a href="${esc(ap.url)}" class="mini-link" target="_blank" rel="noopener noreferrer">${t('advisory')} ↗</a>`:''}</div>`;}
const confidenceText=k=>window.ChangeConfidenceText?.label(language,k)||k;
function scenarioRows(){try{return JSON.parse(buffer('change').scenarios||'[]');}catch(_){return [];}}
function scopeSuggestions(){const b=buffer('change');const get=raw=>{try{return raw.trim()?window.FirewallReview.parse(raw,state.vendor).scopes:[];}catch(_){return [];}};return {before:get(b.current),after:get(b.after)};}
function newScenario(){const scopes=scopeSuggestions();return {name:'',sourceIP:'',destinationIP:'',protocol:'tcp',port:'443',expected:'permit',from:'',to:'',beforeScope:scopes.before.length===1?scopes.before[0]:'',afterScope:scopes.after.length===1?scopes.after[0]:''};}
function scenarioField(k,value,index){const options={protocol:['tcp','udp'],expected:['permit','block'],expectedBefore:['','permit','block']}[k];const label=k==='expected'?t('expected'):t(k);const id='scenario-'+index+'-'+k;return `<div class="scenario-field"><label for="${id}">${esc(label)}</label>${options?`<select id="${id}" data-scenario-row="${index}" data-scenario-field="${k}">${options.map(v=>`<option value="${v}" ${String(value||'')===v?'selected':''}>${k==='protocol'?v.toUpperCase():v?t(v):t('noExpectation')}</option>`).join('')}</select>`:`<input id="${id}" data-scenario-row="${index}" data-scenario-field="${k}" maxlength="200" value="${esc(value??'')}" ${k.endsWith('Scope')?'list="scenario-scopes"':''} ${k==='sourcePort'?'type="number" min="1" max="65535"':''} autocomplete="off">`}</div>`;}
function scenarioBuilder(b){let rows=scenarioRows();if(!rows.length&&b.scenarios==='[]'){rows=[newScenario()];b.scenarios=JSON.stringify(rows);}const scopes=scopeSuggestions();return `<section id="scenario-builder" class="scenario-builder"><h3>${t('trafficBuilder')}</h3><p class="fine-print">${t('scenarioHint')} ${t('policyContextHint')}</p><datalist id="scenario-scopes">${[...new Set([...scopes.before,...scopes.after])].map(v=>`<option value="${esc(v)}"></option>`).join('')}</datalist><div id="scenario-rows">${rows.map((row,i)=>`<article class="scenario-row"><div class="scenario-row-head"><strong>${t('flow')} ${i+1}</strong><button type="button" class="text-button" data-remove-scenario="${i}" aria-label="${t('removeFlow')} ${i+1}">${t('removeFlow')}</button></div><div class="scenario-fields">${['name','sourceIP','destinationIP','protocol','port','expected','from','to'].map(k=>scenarioField(k==='name'?'flowName':k,k==='name'?row.name:row[k],i).replace('data-scenario-field="flowName"','data-scenario-field="name"')).join('')}</div><details class="tool-details" open><summary>${t('scope')}</summary><div class="scenario-fields">${['beforeScope','afterScope','expectedBefore','sourcePort'].map(k=>scenarioField(k,row[k],i)).join('')}</div></details><details class="tool-details"><summary>${esc(confidenceText('contractDetails'))}</summary><div class="scenario-fields">${Object.entries(window.FirewallChangeReview.CONTRACT_FIELDS||{}).map(([k,max])=>`<div class="scenario-field"><label for="scenario-${i}-${k}">${esc(confidenceText(k))}</label><input id="scenario-${i}-${k}" data-scenario-row="${i}" data-scenario-field="${k}" maxlength="${max}" value="${esc(row[k]||'')}" autocomplete="off"></div>`).join('')}</div></details></article>`).join('')}</div><button type="button" class="secondary" id="add-scenario" ${rows.length>=100?'disabled':''}>${t('addFlow')}</button></section><details class="tool-details"><summary>${t('advancedJson')}</summary>${textarea('scenarios-input',t('scenarios'),b.scenarios)}<p class="fine-print">${t('jsonDraft')}</p><button type="button" class="secondary" id="apply-scenarios">${t('applyJson')}</button></details>`;}
function updateScenarioJson(){if($('scenarios-input'))$('scenarios-input').value=buffer('change').scenarios;}
function wireScenarios(){const edit=e=>{const el=e.target.closest('[data-scenario-field]');if(!el)return;const rows=scenarioRows(),row=rows[Number(el.dataset.scenarioRow)];if(!row)return;const f=el.dataset.scenarioField;if(f==='sourcePort'){if(el.value)row[f]=Number(el.value);else delete row[f];}else row[f]=el.value;buffer('change').scenarios=JSON.stringify(rows);updateScenarioJson();invalidate('change');};$('scenario-builder').addEventListener('input',edit);$('scenario-builder').addEventListener('change',edit);$('scenario-builder').addEventListener('click',e=>{const el=e.target.closest('[data-remove-scenario]');if(!el)return;capture();const rows=scenarioRows();rows.splice(Number(el.dataset.removeScenario),1);buffer('change').scenarios=JSON.stringify(rows);invalidate('change');renderWorkspace();});$('add-scenario').addEventListener('click',()=>{capture();const rows=scenarioRows();if(rows.length>=100)return;rows.push(newScenario());buffer('change').scenarios=JSON.stringify(rows);invalidate('change');renderWorkspace();});$('apply-scenarios').addEventListener('click',()=>{try{const raw=$('scenarios-input').value;if(new TextEncoder().encode(raw).length>131072)throw Error('invalidScenarios');const rows=window.FirewallChangeReview.scenarios(JSON.parse(raw));capture();buffer('change').scenarios=JSON.stringify(rows);invalidate('change');renderWorkspace();}catch(_){setStatus(t('scenarioError'),true);}});}
function caseStatus(message,error=false){$('case-status').hidden=false;$('case-status').textContent=message;$('case-status').className='wrap status '+(error?'error':'success');}
function saveCase(){try{capture();const raw=Case.serialize(state,language),url=URL.createObjectURL(new Blob([raw],{type:'application/json;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='weownit-security-canvas-case.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);caseStatus(t('savedHint'));}catch(e){caseStatus(t(e.code==='caseTooLarge'?'caseTooLarge':'invalidCase'),true);}}
async function resumeCase(){const input=$('resume-case'),file=input.files?.[0],ticket=state.revision;if(!file)return;try{if(file.size>Case.MAX_FILE)throw Object.assign(new Error(),{code:'caseTooLarge'});const loaded=Case.validateCase(await file.text()),results={};for(const k of loaded.path){if(loaded.reviewed[k]==='skipped'){results[k]={kind:k,skipped:true};continue;}if(loaded.reviewed[k]!=='reviewed')continue;if(k==='web'&&loaded.web){results.web=loaded.web;continue;}if(['policy','change','hardening','triage'].includes(k)){const b=loaded.buffers[k];if(!b||!b.current.trim()||k==='hardening'&&!b.reference.trim())throw Error('invalidCase');results[k]={...await C.inspectAsync(k,loaded.vendor,b),sample:loaded.samples[k],restored:true};}}if(ticket!==state.revision)return;state.revision++;state.running=false;state.vendor=loaded.vendor;state.concern=loaded.concern;state.path=loaded.path;state.buffers=loaded.buffers;state.notes=loaded.notes;state.samples=loaded.samples;state.results=results;state.asset=loaded.asset;state.bridge=null;const pending=state.path.findIndex(k=>!results[k]);state.index=pending>=0?Math.min(loaded.index,pending):loaded.index;state.view='canvas';language=loaded.language;window.SiteI18n.setLanguage(language);$('start').hidden=true;$('comparison').hidden=true;$('workspace').hidden=false;translate();setComparisonButtons();caseStatus(t('restored'));focusPanel();}catch(e){if(ticket===state.revision)caseStatus(t(e.code==='caseTooLarge'?'caseTooLarge':'invalidCase'),true);}finally{input.value='';}}
function prepareFullTool(){const frame=$('current-frame');$('bridge-return').disabled=true;if(!state.bridge)return;try{const api=frame.contentWindow?.SecurityCanvasFullTools;if(!api)return;api.open(state.bridge.kind,state.vendor,buffer(state.bridge.kind),state.samples[state.bridge.kind]);$('bridge-return').disabled=false;$('bridge-status').textContent='';}catch(_){$('bridge-status').textContent=t('bridgeError');}}
async function importFullTool(){const bridge=state.bridge,ticket=state.revision;if(!bridge)return;$('bridge-return').disabled=true;try{const api=$('current-frame').contentWindow?.SecurityCanvasFullTools;if(!api)throw Error('bridgeUnavailable');const imported=await api.read();if(ticket!==state.revision||state.bridge!==bridge)return;if(imported.vendor!==state.vendor||imported.kind!==bridge.kind||state.index!==bridge.index)throw Error('modeMismatch');const candidate={...state,buffers:{...state.buffers,[bridge.kind]:{...buffer(bridge.kind),...imported.input}},results:{...state.results}};delete candidate.results[bridge.kind];if(bridge.kind==='cve'&&imported.input.cve!==buffer('cve').cve)candidate.asset={...state.asset,assessment:'unverified',ack:false,note:''};Case.serialize(candidate,language);state.buffers=candidate.buffers;state.asset=candidate.asset;invalidate(bridge.kind);state.samples[bridge.kind]=imported.sample;state.bridge=null;canvasView();renderWorkspace();focusPanel();await run();}catch(_){if(ticket===state.revision)$('bridge-status').textContent=t('bridgeError');}finally{$('bridge-return').disabled=false;setComparisonButtons();}}
